import{_ as e,o,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-04-29:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-04-29:: Ceph Orchestration Meeting","date":"2019-04-29T00:00:00.000Z","updated":"2019-05-14T00:00:00.000Z","tags":["Ceph","Rook","Kubernetes","Distributed Storage","ORchestration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-29_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-04-29_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-04-29_-_-_Ceph_Orchestration_Meeting.md"};function s(n,t,a,p,_,g){return o(),i("div",null,[...t[0]||(t[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年4月29日</p><p><strong>会议主题</strong>： Orchestrators 团队会议</p><p><strong>会议内容</strong>：</p><p><strong>一、Rook 1.0.0 更新</strong></p><ul><li>Rook 1.0.0 版本即将发布，代码层面已无阻塞问题。</li><li>新网站开发完成，将与 Rook 1.0.0 版本一同发布，带来新的视觉和用户体验。</li><li>确认 Rook 管理器配置路径需要包含管理器 ID 以确保配置的有效性。</li></ul><p><strong>二、Ceph 与 Tautology 集成</strong></p><ul><li>团队讨论了将 Ceph 与 Tautology 的集成，但遇到了 API 集成难度大等问题。</li><li>建议将测试分为两部分，在 Tautology 和 Cuban Edda 环境中进行。</li><li>需要解决 Docker 镜像构建和不同 Kubernetes 环境测试的问题。</li></ul><p><strong>三、自动化测试</strong></p><ul><li>团队强调了自动化测试的重要性，并分享了各自的环境和测试工具。</li><li>建议构建一个可由所有人使用的测试框架，并讨论了自动化构建 Docker 镜像的问题。</li></ul><p><strong>四、其他事项</strong></p><ul><li>讨论了 Ceph 的内存目标设置问题。</li><li>讨论了 Ceph 与其他存储提供商的集成。</li><li>讨论了即将举行的 Ceph 会议。</li></ul><p><strong>五、行动计划</strong></p><ul><li>审查新网站，确保其与 Rook 1.0.0 版本一同发布。</li><li>解决 Rook 管理器配置路径问题。</li><li>继续推进 Ceph 与 Tautology 的集成。</li><li>构建自动化测试框架。</li><li>解决 Docker 镜像构建问题。</li></ul><p><strong>六、后续行动</strong></p><ul><li>团队成员将根据行动计划继续推进工作。</li><li>团队将定期召开会议，讨论进度和问题。</li></ul>',16)])])}const c=e(r,[["render",s]]);export{h as __pageData,c as default};
